public int findUnsortedSubarray(int[] nums) {
    int start = 0, end = nums.length - 1;
    while (start < nums.length - 1 && nums[start] <= nums[start + 1]) start++;
    while (end > 0 && nums[end] >= nums[end - 1]) end--;
