import java.util.HashMap;
import java.util.Map;

public class Solution {
    public String smallestEquivalentString(String s1, String s2, String baseStr) {
        Map<Character, Character> parent = new HashMap<>();
        for (char ch = 'a'; ch <= 'z'; ch++) {
            parent.put(ch, ch);
        }

        for (int i = 0; i < s1.length(); i++) {
            char root1 = findParent(parent, s1.charAt(i));
            char root2 = findParent(parent, s2.charAt(i));
            if (root1 != root2) {
                parent.put(root1, (char) Math.min(root1, root2));
                parent.put(root2, (char) Math.min(root1, root2));
            }
        }

        StringBuilder sb = new StringBuilder();
        for (char ch : baseStr.toCharArray()) {
            sb.append(findParent(parent, ch));
        }

        return sb.toString();
    }

    private char findParent(Map<Character, Character> parent, char ch) {
        while (parent.get(ch) != ch) {
            ch = parent.get(ch);
        }
        return ch;
    }
}
