# Import necessary libraries
import numpy as np
import matplotlib.pyplot as plt

# Define the function to be integrated
def f(x):
    return x**2

# Define the limits of integration
a = 0
b = 1

# Define the number of subintervals
n = 100

# Calculate the width of each subinterval
h = (b - a) / n

# Initialize the sum of the function values
sum_f = 0

# Calculate the sum of the function values at the midpoints of each subinterval
for i in range(n):
    x_mid = a + (i + 0.5) * h
    sum_f += f(x_mid)

# Calculate the integral using the midpoint rule
integral = h * sum_f

# Print the result
print("The integral of f(x) = x^2 from", a, "to", b, "is", integral)

# Plot the function and the rectangles used in the midpoint rule
x = np.linspace(a, b, 100)
y = f(x)
plt.plot(x, y)
for i in range(n):
    x_mid = a + (i + 0.5) * h
    y_mid = f(x_mid)
    plt.plot([x_mid, x_mid], [0, y_mid], 'r')
    plt.plot([a + i * h, a + (i + 1) * h], [y_mid, y_mid], 'r')
plt.show()
