# Import necessary libraries
import numpy as np
import matplotlib.pyplot as plt

# Define the function to be optimized
def objective_function(x):
    return x**2 + 5*np.sin(x)

# Define the gradient of the function
def gradient(x):
    return 2*x + 5*np.cos(x)

# Define the gradient descent algorithm
def gradient_descent(initial_point, learning_rate, num_iterations):
    x = initial_point
    for i in range(num_iterations):
        x -= learning_rate * gradient(x)
    return x

# Set the initial point, learning rate, and number of iterations
initial_point = 0
learning_rate = 0.1
num_iterations = 100

# Run the gradient descent algorithm
optimal_point = gradient_descent(initial_point, learning_rate, num_iterations)

# Print the optimal point
print("Optimal point:", optimal_point)

# Plot the function and the optimal point
x = np.linspace(-10, 10, 100)
y = objective_function(x)
plt.plot(x, y)
plt.plot(optimal_point, objective_function(optimal_point), 'ro')
plt.xlabel('x')
plt.ylabel('f(x)')
plt.title('Gradient Descent Optimization')
plt.show()
