def grundy(k, ai):
    if k % 2:
        if ai <= 3:
            return G_ODD[ai]
        elif ai % 2:
            return 0
        else:
            p = 0
            j = ai
            while not j & 1:
                p += 1
                j >>= 1
            if j == 3:
