import java.util.*;

public class Solution {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        long s = in.nextLong();
        long[] v = new long[n];
        long min = Long.MAX_VALUE;
        long sum = 0;
        long t = 0;

        for (int i = 0; i < n; i++) {
            v[i] = in.nextLong();
            if (v[i] < min) {
                min = v[i];
            }
            t += v[i];
        }

        if (t < s) {
            System.out.println(-1);
        } else {
            for (int i = 0; i < n; i++) {
                sum += v[i] - min;
                v[i] = min;
            }

            if (sum >= s) {
                System.out.println(min);
            } else {
                s -= sum;
                System.out.println((n * min - s) / n);
            }
        }
    }
}
```

