#!/bin/bash

# Function to check if a string is a palindrome
is_palindrome() {
    local str=$1
    local len=${#str}
    local i j

    for ((i=0, j=len-1; i<j; i++, j--)); do
        if [ "${str:$i:1}" != "${str:$j:1}" ]; then
            return 1 # Not a palindrome
        fi
    done

    return 0 # Palindrome
}

# Function to find the longest palindromic substring
longest_palindrome() {
    local s=$1
    local len=${#s}
    local i j k

    for ((k=len; k>0; k--)); do
        for ((i=0; i<=len-k; i++)); do
            j=$((i+k-1))
            if [ "${s:$i:1}" == "${s:$j:1}" ]; then
                if [ $k -eq 1 ] || [ $k -eq 2 ]; then
                    echo "${s:$i:$k}"
                    return
                else
                    if is_palindrome "${s:$i:$k}"; then
                        echo "${s:$i:$k}"
                        return
                    fi
                fi
            fi
        done
    done

    echo "" # No palindrome found
}

# Read input from stdin
read -r s

# Find and print the longest palindromic substring
longest_palindrome "$s"
