def count_good_subarrays(nums):
    N = len(nums)
    odds, evens = 0, 0
    for i in range(N):
        if i % 2 == 0:
            odds += nums[i]
        else:
            evens += nums[i]
    odds, evens, num_good = evens, odds - nums[0], 0
    if odds == evens:
        num_good += 1
    for i in range(1, N):
        if i % 2 == 1:
            odds = odds - nums[i] + nums[i-1]
        else:
            evens = evens - nums[i] + nums[i-1]
        if odds == evens:
            num_good += 1
    return num_good

