					ans = Math.max(ans, 1 + solve(i + 1, n - j, 0));
				else
					ans = Math.max(ans, solve(i + 1, n - j, 1));
			} else {
				if ((s[i] == 'F' && j % 2 == 0) || (s[i] == 'T' && j % 2 == 1))
					ans = Math.max(ans, -1 + solve(i + 1, n - j, 1));
				else
					ans = Math.max(ans, solve(i + 1, n - j, 0));
			}
		}
		return dp[i][n][dir] = ans;
	}

