            for (int i = 0; i < n - 1; ++ i) {
                int a = reader.nextInt() - 1;
                int b = reader.nextInt() - 1;
                edges[a].add(b);
                edges[b].add(a);
            }
            answer = pairs(n) * pairs(n);
            solve(-1, 0);
            writer.println(answer);
        } catch (IOException ex) { 
        }
        writer.close();
    }

    InputReader reader;
    PrintWriter writer;

