    s = input()

    # Check if the string is already in the desired format
    if s == "2020":
        print("YES")
    else:
        # Check if the string can be rearranged to form "2020"
        if "2" in s and "0" in s and "2" in s and "0" in s:
            print("YES")
        else:
            print("NO")

