        HashMap<Integer, Integer> setH = new HashMap<>();
        HashMap<Integer, Integer> setA = new HashMap<>();
        Scanner s = new Scanner(System.in);
        int n = s.nextInt();
        for (int i = 0; i < n; i++) {
            int h = s.nextInt();
